<?phpheader('Access-Control-Allow-Origin: *');require_once 'config.php';require_once 'jwt.php';$headers = getallheaders();$tokendata = $headers['X-Authorization'] ?? '';if ($_SERVER['REQUEST_METHOD'] === 'POST') {	if ($tokendata) {		$token_array = explode(" ", $tokendata);		if($token_array[0] == 'Bearer'){			$token = $token_array[1];			$decodedToken = verifyToken($token, JWT_SECRET_KEY,$conn);			if ($decodedToken) {				$_REQUEST = json_decode(file_get_contents('php://input'), true);				$arrResults = array();				$survey_id = $_REQUEST['survey_id'];				if($survey_id!=''){					$Usersql = "SELECT id, form_version, survey_name FROM survey where id='".$survey_id."'  ";					$return_arr = array();					mysqli_set_charset($conn, 'utf8');					$fetch = mysqli_query($conn, $Usersql);					$rows = array();					while ($row = mysqli_fetch_array($fetch, MYSQLI_ASSOC))					{						$row['survey_name'] = $row['survey_name'];						$rows = $row;					}					echo json_encode($rows);					exit;				}				else{					$rows = array("status"=>0,"message"=>"Survey Id Are Required.");					echo json_encode($rows);					exit;				}			}else{				$response = ["status"=>0,"message" => "Token not verified"];				echo json_encode($response);				exit;			}		}else{			$response = ["status"=>0,"message" => "Auth request is invalid"];			echo json_encode($response);			exit;		}	}else{		http_response_code(401); // Unauthorized status code		$response = ["status"=>0,"error" => "Invalid token"];		echo json_encode($response);		exit;	}} else {	http_response_code(405); // Method Not Allowed	$response = ["status"=>0, "message" => "The call method not allowed"];	echo json_encode($response);	exit;}